#include <cstdio>

#include <cstring>

#include <algorithm>

using namespace std;

char a[100005],b[100005];

int dp[100005][2];

int main()

{

    int q;

    scanf("%d",&q);

    while(q--)

    {

        scanf("%s%s",a,b);

        int la=strlen(a),lb=strlen(b);

        memset(dp,0,sizeof(dp));

        for(int i=0;i<=la;i++)

            dp[i][0]=i*3;

        for(int i=0;i<=lb;i++)

            dp[0][i%2]=i*2;

        for(int i=1;i<=la;i++)

        {

            for(int j=1;j<=lb;j++)

            {

                dp[i][j%2]=min(dp[i-1][j%2]+3,dp[i][(j-1)%2]+2);

                if(a[i-1]==b[j-1])

                    dp[i][j%2]=min(dp[i][j%2],dp[i-1][(j-1)%2]);

                else

                    dp[i][j%2]=min(dp[i][j%2],dp[i-1][(j-1)%2]+2);

            }

        }

        printf("%d\n",dp[la][lb%2]);

    }

    return 0;

}

