unsigned long adler32(unsigned long adler, const unsigned char* buf, size_t len) {
	unsigned long s1 = adler & 0xFFFF;
	unsigned long s2 = adler >> 16;
	for (size_t i = 0; i < len; ++i) {
		s1 = (s1 + buf[i]) % 65521;
		s2 = (s2 + s1) % 65521;
	}
	return (s2 << 16) | s1;
}

