bool stringmatchlen(const char *p, int plen, const char *s, int slen, int nocase) {
  for (int i = 0; i < plen; i++) {
    if (p[i] == '*') {
      for (int j = 0; j <= slen - (plen - i); j++) {
        if (stringmatchlen(p + i + 1, plen - i - 1, s + j, slen - j, nocase)) return true;
      }
      return false;
    } else if (p[i] == '?') {
      if (i == plen - 1) return true;
      continue;
    } else if (p[i] == '[') {
      int j = i + 1;
      bool neg = false;
      if (p[j] == '^') neg = true, j++;
      bool match = false;
      while (p[j] != ']') {
        if (p[j] == '\\' && j + 1 < plen) j++;
        if (match) break;
        if (j + 2 < plen && p[j + 1] == '-' && p[j + 2] != ']') {
          if (match = (p[j] <= s[i] && s[i] <= p[j + 2])) j += 3;
          else j += 2;
        } else {
          if (match = match(p[j], s[i], nocase)) j++;
          else j++;
        }
      }
      if (neg) match = !match;
      if (!match) return false;
      i = j;
    } else if (p[i] == '\\') {
      if (i + 1 < plen && !match(p[i + 1], s[i], nocase)) return false;
      i++;
    } else {
      if (!match(p[i], s[i], nocase)) return false;
    }
    if (i == plen - 1) return true;
  }
  return false;
}

