  while (pi < patternLen && si < stringLen) {
    if (pattern[pi] == '*') {
      while (pi < patternLen && pattern[pi] == '*') pi++;
      if (pi == patternLen) return true;
      while (si < stringLen) {
        if (stringmatchlen(pattern + pi, patternLen - pi, string + si, stringLen - si, nocase)) return true;
        si++;
      }
      return false;
    } else if (pattern[pi] == '?') {
      pi++;
      si++;
    } else if (pattern[pi] == '[') {
      pi++;
      bool negated = false;
      if (pattern[pi] == '^') {
        negated = true;
        pi++;
      }
      bool matched = false;
      while (pi < patternLen && pattern[pi] != ']') {
        if (pattern[pi] == '\\' && pi + 1 < patternLen) {
          pi++;
          if (match(pattern[pi], string[si], nocase)) matched = true;
        } else if (pi + 2 < patternLen && pattern[pi + 1] == '-' && pattern[pi + 2] != ']') {
          char lo = pattern[pi];
          char hi = pattern[pi + 2];
          if (lo > hi) std::swap(lo, hi);
          if (nocase) {
            lo = std::tolower(lo);
            hi = std::tolower(hi);
          }
          if (lo <= string[si] && string[si] <= hi) matched = true;
          pi += 2;
        } else {
          if (match(pattern[pi], string[si], nocase)) matched = true;
        }
        pi++;
      }
      if (pi == patternLen || pattern[pi] != ']') return false;
      pi++;
      if (negated) matched = !matched;
      if (!matched) return false;
      si++;
    } else if (pattern[pi] == '\\') {
      pi++;
      if (pi == patternLen) return false;
      if (!match(pattern[pi], string[si], nocase)) return false;
      pi++;
      si++;
    } else {
      if (!match(pattern[pi], string[si], nocase)) return false;
      pi++;
      si++;
    }
  }
  while (pi < patternLen && pattern[pi] == '*') pi++;
  return pi == patternLen && si == stringLen;
