        if (pi + 2 < plen && p[pi + 1] == '-' && p[pi + 2] != ']') {
          char lo = p[pi], hi = p[pi + 2];
          if (nocase) lo = tolower(lo), hi = tolower(hi);
          if (lo > hi) std::swap(lo, hi);
          if (lo <= s[si] && s[si] <= hi) match = true;
          pi += 3;
        } else {
          if (match(p[pi], s[si], nocase)) match = true;
          pi++;
        }
      }
      if (pi == plen || p[pi] != ']') return false;
      pi++, si++;
      if (neg) match = !match;
      if (!match) return false;
    } else if (p[pi] == '\\') {
      pi++;
      if (pi == plen) return false;
      if (!match(p[pi], s[si], nocase)) return false;
      pi++, si++;
    } else {
      if (!match(p[pi], s[si], nocase)) return false;
      pi++, si++;
    }
  }
  while (pi < plen && p[pi] == '*') pi++;
  return pi == plen && si == slen;
}

int main() {
  int q; scanf("%d", &q);
  while (q--) {
    scanf("%s %s", p, s);
    int nocase; scanf("%d", &nocase);
    puts(stringmatchlen(p, strlen(p), s, strlen(s), nocase) ? "YES" : "NO");
  }
  return 0;
}

#include <cctype>
#include <cstdio>
#include <cstring>

char p[1 << 16], s[1 << 16];

inline bool match(char a, char b, int nocase) {
  if (!nocase) return a == b;
  return tolower(a) == tolower(b);
}

bool stringmatchlen(const char *pattern, int patternLen,
                    const char *string, int stringLen, int nocase) {
  while (patternLen && stringLen) {
    switch (pattern[0]) {
      case '*': {
        while (patternLen && pattern[1] == '*') {
          pattern++;
          patternLen--;
        }
        if (patternLen == 1) return true; // match
        while (stringLen) {
          if (stringmatchlen(pattern + 1, patternLen - 1, string, stringLen, nocase)) return true; // match
          string++;
          stringLen--;
        }
        return false; // no match
      }
      case '?':
        string++;
        stringLen--;
        break;
      case '[': {
        int negate, match;

        pattern++;
        patternLen--;
        negate = patternLen && pattern[0] == '^';
        if (negate) {
          pattern++;
          patternLen--;
        }
        match = 0;
        while (1) {
          if (patternLen >= 2 && pattern[0] == '\\') {
            pattern++;
            patternLen--;
            if (pattern[0] == string[0]) match = 1;
          } else if (patternLen == 0) {
            pattern--;
            patternLen++;
            break;
          } else if (pattern[0] == ']') {
            break;
          } else if (patternLen >= 3 && pattern[1] == '-') {
            int start = pattern[0];
            int end = pattern[2];
            int c = string[0];
            if (start > end) {
              int t = start;
              start = end;
              end = t;
            }
            if (nocase) {
              start = tolower(start);
              end = tolower(end);
              c = tolower(c);
            }
            pattern += 2;
            patternLen -= 2;
            if (c >= start && c <= end) match = 1;
          } else {
            if (!nocase) {
              if (pattern[0] == string[0]) match = 1;
            } else {
              if (tolower((int)pattern[0]) == tolower((int)string[0])) match = 1;
            }
          }
          pattern++;
          patternLen--;
        }
        if (negate) match = !match;
        if (!match) return false; // no match
        string++;
        stringLen--;
        break;
      }
      case '\\':
        if (patternLen >= 2) {
          pattern++;
          patternLen--;
        }
        // fall through
      default:
        if (!match(pattern[0], string[0], nocase)) return false; // no match
        string++;
        stringLen--;
        break;
    }
    pattern++;
    patternLen--;
    if (stringLen == 0) {
      while (patternLen && *pattern == '*') {
        pattern++;
        patternLen--;
      }
      break;
    }
  }
  if (patternLen == 0 && stringLen == 0) return true;
  return false;
}

int main() {
  int q; scanf("%d", &q);
  for (int i = 0; i < q; i++) {
    int nocase;
    scanf("%s %s %d", p, s, &nocase);
    puts(stringmatchlen(p, strlen(p), s, strlen(s), nocase) ? "YES" : "NO");
  }
  return 0;
}
